create table if not exists public.platform_domains(id uuid primary key default gen_random_uuid(),clinica_id uuid references public.clinicas(id)on delete cascade,domain text not null unique check(domain~'^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$'),purpose text not null default'app'check(purpose in('app','email')),status text not null default'pending'check(status in('pending','verified','error')),verification_token uuid not null default gen_random_uuid(),dns_result jsonb,checked_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null default auth.uid()references auth.users(id));alter table public.platform_domains enable row level security;create policy"plataforma gerencia dominios"on public.platform_domains for all to authenticated using(public.is_platform_admin())with check(public.is_platform_admin());
revoke all on table public.platform_domains from anon;grant select,insert,update,delete on public.platform_domains to authenticated;
